#include <SDL3/SDL.h>
#include <epoxy/gl.h>
#include <vector>
#include <cstdio>
#include <algorithm>
#include <cstdint>
namespace GAGCore {bool prepareNativeMipmaps(unsigned,SDL_Surface*); void releaseNativeMipmaps(SDL_GLContext);}
int main(){SDL_Init(SDL_INIT_VIDEO);SDL_GL_SetAttribute(SDL_GL_CONTEXT_MAJOR_VERSION,2);SDL_GL_SetAttribute(SDL_GL_CONTEXT_MINOR_VERSION,1);auto*w=SDL_CreateWindow("mip probe",64,64,SDL_WINDOW_OPENGL|SDL_WINDOW_HIDDEN);auto c=SDL_GL_CreateContext(w);if(!c){puts(SDL_GetError());return 2;}printf("GL=%s version=%s glsl=%s integer_ext=%d\n",glGetString(GL_RENDERER),glGetString(GL_VERSION),glGetString(GL_SHADING_LANGUAGE_VERSION),SDL_GL_ExtensionSupported("GL_EXT_gpu_shader4"));int cases=0;for(auto size: {std::pair{1,1}, {1,256},{256,1},{256,256},{1024,512}})for(int mode=0;mode<3;++mode){auto*s=SDL_CreateSurface(size.first,size.second,SDL_PIXELFORMAT_ARGB8888);uint32_t random=42;auto*ptr=(uint32_t*)s->pixels;for(int i=0;i<s->w*s->h;++i){random^=random<<13;random^=random>>17;random^=random<<5;ptr[i]=mode==0?random&0xffffff:mode==1?random|0xff000000:random;}std::vector<uint32_t> ref(ptr,ptr+s->w*s->h);GLuint t;glGenTextures(1,&t);glBindTexture(GL_TEXTURE_2D,t);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_LINEAR);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_LINEAR_MIPMAP_LINEAR);if(!GAGCore::prepareNativeMipmaps(t,s)){puts("GPU fallback");return 3;}int x=s->w,y=s->h,l=0;for(;;){std::vector<uint32_t> got(x*y);glGetTexImage(GL_TEXTURE_2D,l,GL_BGRA,GL_UNSIGNED_INT_8_8_8_8_REV,got.data());for(int i=0;i<x*y;++i)if(got[i]!=ref[i]){printf("bad size%d,%d mode%d level%d idx%d got%x want%x error%x\n",s->w,s->h,mode,l,i,got[i],ref[i],glGetError());return 4;}if(x==1&&y==1)break;int nx=std::max(1,x/2),ny=std::max(1,y/2);std::vector<uint32_t> next(nx*ny);for(int yy=0;yy<ny;++yy)for(int xx=0;xx<nx;++xx){uint32_t box[4];int a=0;for(int z=0;z<4;++z){box[z]=ref[std::min(y-1,yy*2+z/2)*x+std::min(x-1,xx*2+z%2)];a+=box[z]>>24;}uint32_t v=((a+2)/4)<<24;for(int shift=0;shift<24;shift+=8){int sum=0;for(auto p:box)sum+=((p>>shift)&255)*(p>>24);if(a)v|=((sum+a/2)/a)<<shift;}next[yy*nx+xx]=v;}ref.swap(next);x=nx;y=ny;++l;}glDeleteTextures(1,&t);SDL_DestroySurface(s);++cases;}printf("passed %d exact mip cases error=%x\n",cases,glGetError());GAGCore::releaseNativeMipmaps(c);SDL_GL_DestroyContext(c);SDL_DestroyWindow(w);SDL_Quit();}
